import{_ as i,C as n,c as p,o as s,a8 as l,j as e,a as t,G as r}from"./chunks/framework.DBQiK-q5.js";const d="/sealdice-manual-next/assets/platform-qq-turnoff.BeOWAmaj.png",v=JSON.parse('{"title":"QQ","description":"","frontmatter":{"lang":"zh-cn","title":"QQ"},"headers":[],"relativePath":"deploy/platform-qq.md","filePath":"deploy/platform-qq.md","lastUpdated":1787636036000}'),g={name:"deploy/platform-qq.md"},u={id:"内置客户端",tabindex:"-1"},k={id:"lagrange-milky",tabindex:"-1"},Q={id:"yogurt",tabindex:"-1"},b={id:"chronocat",tabindex:"-1"},h={id:"chronocat-satori-协议",tabindex:"-1"};function m(f,a,y,L,q,c){const o=n("Badge");return s(),p("div",null,[a[35]||(a[35]=l('<h1 id="qq" tabindex="-1">QQ <a class="header-anchor" href="#qq" aria-label="Permalink to &quot;QQ&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本节内容</p><p>本节将包含你在 QQ 平台接入海豹核心需要了解的特定内容。</p></div><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><h3 id="有关-qq-平台机器人的说明" tabindex="-1">有关 QQ 平台机器人的说明 <a class="header-anchor" href="#有关-qq-平台机器人的说明" aria-label="Permalink to &quot;有关 QQ 平台机器人的说明&quot;">​</a></h3><p>直至目前，绝大部分群聊中的 QQ 机器人采用「<strong>假用户</strong>」方式，即通过第三方软件接入注册的另一个 QQ。<strong>QQ 官方一直在对第三方实现进行技术与非技术层面的多重打击。</strong></p><p>从目前的表现看来，QQ 官方会对账号行为进行检测，来区分出账号是否是正常用户（如不正常的登录方式，以不合理的速度在多地区登录等等）。我们无法得知具体的检测细节，但已证实的是，当 QQ 账号用作机器人并被检测到时，该 QQ 会视为风险账号，被官方予以警告，封禁，临时甚至 <strong>永久冻结</strong> 的惩罚。</p><p>尽管不同方案之间的差异很大（比如基于 Android QQ 协议的 Go-Cqhttp 已经<strong>基本不可用</strong>，而 <a href="#lagrange-milky">Lagrange.Milky</a> 和 <a href="#NapCat">NapCat</a> 等基于 NTQQ 的方案仍在维护），但需要明白的是，这些方案都由社区第三方软件提供，实质上以 QQ 官方角度等同于「<strong>外挂软件</strong>」，并不受到官方支持（甚至是被打击的目标）。</p><p>因此，<em>是否在 QQ 平台搭建这样的非官方机器人取决于你的慎重考虑</em>。同时，第三方方案的可用性也可能会随时间推移而存在变化，海豹官方无法做出任何保证。</p><p>目前，仅有 <a href="./platform-qq-official.html">官方机器人服务</a> 是被 QQ 官方认可的机器人方案。其开放范围和具体能力由 QQ 开放平台决定。</p><p>如果有可能，建议迁移到其它平台，在 QQ 平台选择何种方式取决于你自己的选择。</p><div class="danger custom-block"><p class="custom-block-title">危险</p><p>倘若出现账号被封禁等情况，海豹官方无力解决此类问题，也不对相应后果负责。</p></div><h3 id="对接引导" tabindex="-1">对接引导 <a class="header-anchor" href="#对接引导" aria-label="Permalink to &quot;对接引导&quot;">​</a></h3><p>所有支持的途径参见目录，本节提供了多种对接途径的引导。</p>',13)),e("p",null,[a[0]||(a[0]=t("使用正式版 ",-1)),r(o,{type:"tip",text:"v1.6.0"}),a[1]||(a[1]=t(" 时，非容器部署的新用户可从",-1)),a[2]||(a[2]=e("a",{href:"#内置客户端"},"内置客户端",-1)),a[3]||(a[3]=t("开始。需要自行维护协议端、跨主机连接或使用 Docker 时，再选择分离部署。",-1))]),a[36]||(a[36]=l('<p>对于需要使用更加灵活的方案的用户，我们推荐如下：</p><ul><li>需要由海豹管理 QQ 客户端进程的，见<a href="#内置客户端">内置客户端</a>；</li><li>使用 OneBot 11 分离部署的，见 <a href="#llbot">LLBot</a> 或 <a href="#NapCat">NapCat</a>；</li><li>使用 Milky 分离部署的，见 <a href="#lagrange-milky">Lagrange.Milky</a> 或 <a href="#yogurt">Yogurt</a>；</li><li>通过 docker 部署海豹的，见 <a href="./platform-qq-docker.html">QQ - Docker 中的海豹</a>；</li><li>如果你有 QQ 官方机器人权限，见 <a href="./platform-qq-official.html">官方机器人</a>；</li><li>Go-cqhttp 与 QSign 方案因可用性原因已被弃用。<strong>我们不建议任何用户再使用此方式部署 QQ 接入，同时强烈建议正在使用该方案的用户迁移</strong>。</li></ul><p>不同的对接方式适应不同的情况，可能会存在途径特有的功能缺失和其它问题，请根据自己的情况选择适合的方式。</p><div class="warning custom-block"><p class="custom-block-title">注意：对接基于 NTQQ PC 端协议的 QQ 方案时，注意对方是否支持 <code>戳一戳</code> 功能</p><p>Lagrange.Milky、Yogurt、LLBot 和 NapCat 等基于 NTQQ PC 的 QQ 方案，在旧版本中可能缺失该功能。</p><p>使用旧协议端且持续出现报错时，请先更新对应实现；暂时无法更新的，应<strong>关闭</strong>位于 <code>综合设置</code> - <code>基本设置</code> 的 <code>启用戳一戳</code> 开关，以免产生不必要的报错信息。</p><img src="'+d+'" alt="关闭戳一戳开关" width="80%"></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p>Lagrange.OneBot、Lagrange.Milky、Yogurt、LLBot 和 NapCat 都占用 PC 端协议。在使用这些连接方式时，不可同时登录 PC 端 QQ，否则将导致挤占下线。</p><p>由于 QQ 的登录策略，PC 端协议可能需要定期重新登录；实际周期以 QQ 登录状态为准。</p></div>',5)),e("h2",u,[a[4]||(a[4]=t("内置客户端 ",-1)),r(o,{type:"tip",text:"v1.5.1"}),a[5]||(a[5]=t()),a[6]||(a[6]=e("a",{class:"header-anchor",href:"#内置客户端","aria-label":'Permalink to "内置客户端 <Badge type="tip" text="v1.5.1" />"'},"​",-1))]),e("p",null,[a[7]||(a[7]=t("自",-1)),r(o,{type:"tip",text:"v1.5.1"}),a[8]||(a[8]=t("起，海豹核心可以直接启动自带的 ",-1)),a[9]||(a[9]=e("code",null,"Lagrange.Milky",-1)),a[10]||(a[10]=t(" 或 ",-1)),a[11]||(a[11]=e("code",null,"Yogurt",-1)),a[12]||(a[12]=t("，并自动生成仅供本机使用的 Milky 连接地址、访问令牌和配置文件。",-1))]),a[37]||(a[37]=l('<div class="warning custom-block"><p class="custom-block-title">使用限制</p><ul><li>Docker 等容器模式不能使用这两种内置客户端，请改用分离部署。</li><li>登录期间不要在电脑上同时登录同一 QQ，否则可能互相挤下线。</li><li>请使用完整的官方发布包。只替换 <code>sealdice-core</code> 可执行文件时，可能缺少对应客户端程序。</li></ul></div><h3 id="内置-lagrange-milky" tabindex="-1">内置 Lagrange.Milky <a class="header-anchor" href="#内置-lagrange-milky" aria-label="Permalink to &quot;内置 Lagrange.Milky&quot;">​</a></h3><ol><li>打开海豹 WebUI，进入「账号设置」，点击添加账号。</li><li>平台选择「QQ」，连接方式选择「内置 Lagrange.Milky」。</li><li>填写作为骰子的 QQ 号并继续。</li><li>等待页面显示二维码，用已登录目标账号的手机 QQ 扫码并确认。</li><li>等待账号状态变为「已连接」。</li></ol><p>二维码只在短时间内有效。页面提示二维码过期或账号状态变为「失败」时，删除这条失败的连接后重新添加并扫码。</p><h3 id="内置-yogurt" tabindex="-1">内置 Yogurt <a class="header-anchor" href="#内置-yogurt" aria-label="Permalink to &quot;内置 Yogurt&quot;">​</a></h3><ol><li>打开海豹 WebUI，进入「账号设置」，点击添加账号。</li><li>平台选择「QQ」，连接方式选择「内置 Yogurt」。</li><li>填写作为骰子的 QQ 号并继续，其余连接参数由海豹自动生成。</li><li>等待二维码出现，用目标账号扫码并确认。</li><li>等待账号状态变为「已连接」。</li></ol><p>Yogurt 是非容器部署时的默认内置选择。二维码过期后需要删除失败连接并重新添加，不能继续扫描旧二维码。</p><h2 id="分离部署" tabindex="-1">分离部署 <a class="header-anchor" href="#分离部署" aria-label="Permalink to &quot;分离部署&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">分离部署</p><p>不同于内置客户端，分离部署为海豹核心和 QQ 登录框架分别启动，然后按照各个框架的连接协议将海豹核心和 QQ 登录框架连接起来。</p><p>相比之下分离部署有更强的稳定性，但操作难度也有一定程度的增加。</p></div><div class="danger custom-block"><p class="custom-block-title">公网机器部署时的端口暴露风险</p><p>分离部署时，会启用比内置登录更多的网络服务。请在配置防火墙时留意，避免这些服务端口暴露于公网。如确需公网访问，请设置强密码，以保障骰子安全。</p></div>',10)),e("h3",k,[a[13]||(a[13]=t("Lagrange.Milky ",-1)),r(o,{type:"tip",text:"v1.5.1"}),a[14]||(a[14]=t()),a[15]||(a[15]=e("a",{class:"header-anchor",href:"#lagrange-milky","aria-label":'Permalink to "Lagrange.Milky <Badge type="tip" text="v1.5.1" />"'},"​",-1))]),e("p",null,[a[16]||(a[16]=t("海豹从 ",-1)),r(o,{type:"tip",text:"v1.5.1"}),a[17]||(a[17]=t(" 开始支持通过 ",-1)),a[18]||(a[18]=e("code",null,"Lagrange.Milky",-1)),a[19]||(a[19]=t(" 接入 Milky。",-1))]),a[38]||(a[38]=l('<p><code>Lagrange.Milky</code> 是基于 Lagrange.Core.V2 的 Milky 协议实现。</p><h4 id="下载-lagrange-milky" tabindex="-1">下载 Lagrange.Milky <a class="header-anchor" href="#下载-lagrange-milky" aria-label="Permalink to &quot;下载 Lagrange.Milky&quot;">​</a></h4><p>请按照 <a href="https://github.com/LagrangeDev/Lagrange.core" target="_blank" rel="noreferrer">Lagrange.Milky</a>和 <a href="https://lagrangedev.github.io/Lagrange.Milky.Document/" target="_blank" rel="noreferrer">Lagrange.Milky 文档</a> 自行完成安装、登录和配置。</p><h4 id="海豹连接" tabindex="-1">海豹连接 <a class="header-anchor" href="#海豹连接" aria-label="Permalink to &quot;海豹连接&quot;">​</a></h4><p>启动协议端后，在海豹 WebUI 的「账号设置」中，在「账号类型」处选择「QQ」,在「QQ 协议」处选择「Milky 协议 (分离)」添加 Milky 连接，填写 Lagrange.Milky 实际配置文件中提供的 WebSocket、HTTP API 地址 和<code>Token</code>。</p>',5)),e("h3",Q,[a[20]||(a[20]=t("Yogurt ",-1)),r(o,{type:"tip",text:"v1.5.1"}),a[21]||(a[21]=t()),a[22]||(a[22]=e("a",{class:"header-anchor",href:"#yogurt","aria-label":'Permalink to "Yogurt <Badge type="tip" text="v1.5.1"/>"'},"​",-1))]),e("p",null,[a[23]||(a[23]=t("海豹从 ",-1)),r(o,{type:"tip",text:"v1.5.1"}),a[24]||(a[24]=t(" 开始支持通过 ",-1)),a[25]||(a[25]=e("code",null,"Yogurt",-1)),a[26]||(a[26]=t(" 接入 Milky。",-1))]),a[39]||(a[39]=l('<p><a href="https://github.com/SaltifyDev/milky" target="_blank" rel="noreferrer">Yogurt</a>是基于 acidify-core 实现的 Milky 协议端。</p><h4 id="下载-yogurt" tabindex="-1">下载 Yogurt <a class="header-anchor" href="#下载-yogurt" aria-label="Permalink to &quot;下载 Yogurt&quot;">​</a></h4><p>请参照<a href="https://acidify.ntqqrev.org/docs/yogurt/start" target="_blank" rel="noreferrer">Yogurt 手册</a> 进行安装、登录以及配置。</p><h4 id="海豹连接-1" tabindex="-1">海豹连接 <a class="header-anchor" href="#海豹连接-1" aria-label="Permalink to &quot;海豹连接&quot;">​</a></h4><p>启动协议端后，在海豹 WebUI 的「账号设置」中，在「账号类型」处选择「QQ」,在「QQ 协议」处选择「Milky 协议 (分离)」添加 Milky 连接，填写 Yogurt 实际配置文件中提供的 WebSocket、HTTP API 地址 和<code>Token</code>。</p><p>成功连接后即可使用。</p><div class="warning custom-block"><p class="custom-block-title">注意：</p><p><code>Yogurt</code> 与 <code>Lagrange.Milky</code> 需要自行申请 Signer Token 并配置到配置文件中，否则，可能无法正常启动。获取 Signer Token 参见 <a href="https://github.com/LagrangeDev/SignApiGuide" target="_blank" rel="noreferrer">文档</a>，此处不做赘述。</p></div><h3 id="llbot" tabindex="-1">LLBot <a class="header-anchor" href="#llbot" aria-label="Permalink to &quot;LLBot&quot;">​</a></h3><p><a href="https://github.com/LLOneBot/LuckyLilliaBot" target="_blank" rel="noreferrer">LLBot</a>是原 LLOneBot、现 LuckyLiliaBot 项目当前使用的官方简称。 <code>LLOneBot</code> 或 <code>LLTwoBot</code> 均指这一项目的早期名称。为防止误解，本手册统一使用 <code>LLBot</code> 对该项目进行代称。</p><p>请按照 <a href="https://luckylillia.com/" target="_blank" rel="noreferrer">LLBot 文档</a>完成安装并启用 OneBot 11 正向或反向 WebSocket。 随后在海豹 WebUI 的「账号设置」添加对应的 OneBot 11 连接；端口、访问令牌。</p><p>成功连接后即可使用。</p><div class="warning custom-block"><p class="custom-block-title">注意：</p><p>在 <code>v8.0.9</code> 以及之后版本的 LLBOT，可能需要向 LLBOT 开发组申请 AUTH TOKEN，详细申请流程请自行加入 LLBOT 用户群完成，不在此进行赘述。</p></div><h3 id="napcat" tabindex="-1">NapCat <a class="header-anchor" href="#napcat" aria-label="Permalink to &quot;NapCat&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">NapCat</p><p><a href="https://github.com/NapNeko/NapCat" target="_blank" rel="noreferrer">NapCat</a> 是在后台低占用运行的无头（没有界面）的 NTQQ，具体占用会因人而异，QQ 群、好友越多占用越高。</p><p><a href="https://napneko.github.io" target="_blank" rel="noreferrer">NapCat 官方文档</a></p></div><div class="warning custom-block"><p class="custom-block-title">使用此方案的用户请注意不要随意 <em>更新</em> QQ 客户端。</p><p>由于 QQ 客户端检测机制的变化，更新 QQ 客户端后可能导致方案不可用，并且更新后需要重新安装登录框架，所以不建议用户随意更新 QQ 客户端。</p></div><p>NapCat 是基于官方 NTQQ 实现的 Bot 框架，因此在开始前，你需要根据 <a href="https://napneko.github.io/guide/start-install" target="_blank" rel="noreferrer">NapCat</a> 的手册安装官方 QQ，若 QQ 版本过低会导致程序无法正常启动。</p><h4 id="下载-napcat" tabindex="-1">下载 NapCat <a class="header-anchor" href="#下载-napcat" aria-label="Permalink to &quot;下载 NapCat&quot;">​</a></h4><p>请按照 <a href="https://napneko.github.io/guide/start-install" target="_blank" rel="noreferrer">NapCat 官方手册</a> 下载安装，然后按照 <a href="https://napneko.github.io/config/basic" target="_blank" rel="noreferrer">基础配置</a> 和自己的需求修改配置文件。</p><h4 id="海豹连接-2" tabindex="-1">海豹连接 <a class="header-anchor" href="#海豹连接-2" aria-label="Permalink to &quot;海豹连接&quot;">​</a></h4><p>进入海豹 Web UI 的「账号设置」新增链接，按照自己的配置文件选择 onebot11 账号类型，填写 QQ 号和「连接地址」。</p><p>成功连接后即可使用。</p>',21)),e("h3",b,[a[27]||(a[27]=t("Chronocat ",-1)),r(o,{type:"tip",text:"v1.4.2"}),a[28]||(a[28]=t()),a[29]||(a[29]=e("a",{class:"header-anchor",href:"#chronocat","aria-label":'Permalink to "Chronocat <Badge type="tip" text="v1.4.2" />"'},"​",-1))]),e("p",null,[a[30]||(a[30]=t("从 ",-1)),r(o,{type:"tip",text:"v1.4.5"}),a[31]||(a[31]=t(" 开始适配了与 Chronocat 的 Satori 协议连接。",-1))]),a[40]||(a[40]=e("h4",{id:"安装-chronocat",tabindex:"-1"},[t("安装 Chronocat "),e("a",{class:"header-anchor",href:"#安装-chronocat","aria-label":'Permalink to "安装 Chronocat"'},"​")],-1)),a[41]||(a[41]=e("p",null,[t("请按照 "),e("a",{href:"https://chronocat.vercel.app/guide/install/shell",target:"_blank",rel:"noreferrer"},"官方手册"),t(" 安装 Chronocat。")],-1)),e("h4",h,[a[32]||(a[32]=t("Chronocat Satori 协议 ",-1)),r(o,{type:"tip",text:"v1.4.5"}),a[33]||(a[33]=t()),a[34]||(a[34]=e("a",{class:"header-anchor",href:"#chronocat-satori-协议","aria-label":'Permalink to "Chronocat Satori 协议 <Badge type="tip" text="v1.4.5" />"'},"​",-1))]),a[42]||(a[42]=e("p",null,"在账号添加中，选择「[WIP]Satori」，填写相应信息进行连接。",-1))])}const C=i(g,[["render",m]]);export{v as __pageData,C as default};
